          case 'second': return <Choice branch={mode} first={rows.map((row, index) => <Row key={row.id} label={<b>Row {index + 1}</b>}>{row.name}<Value>{row.secret}</Value></Row>)} other="Second fallback" />;
          default: return <p>Default case {rows.map((row, index) => <Row key={row.id} label={<b>Row {index + 1}</b>}>{row.name}<Value>{row.secret}</Value></Row>)}</p>;
        }
      } catch (Choice) { return <Choice>Catch content {rows.map((row, index) => <Row key={row.id} label={<b>Row {index + 1}</b>}>{row.name}<Value>{row.secret}</Value></Row>)}</Choice>; }
      finally { record(<span>Finished {count}</span>); }
